-- =====================================================================
-- 0019 — محتوى صفحة التعريف النهائي كما اعتمدته إدارة المشروع (ملاحظة ٩٣)
--   النص من مستند الإدارة حرفًا بحرف، مع إشارات إلى الرسوم التوضيحية
--   التي ترسمها الواجهة (diagram) بلا نص إضافي من عندها.
-- =====================================================================

insert into public.page_content (key, content, updated_at)
values ('about', '{"badge": "مبادرة من إدارة مشروع خادم الحرمين الشريفين لترجمة خطب الحرمين الشريفين", "h1": "منصة إدارة ترجمة خطب الحرمين الشريفين", "lead": "من الأصل العربي إلى الترجمة المعتمدة؛ بيئة عمل موحدة، ومراجعات متخصصة، ومسؤوليات واضحة.", "note": "يصف هذا العرض ما هو قائم في المنصة، عدا قسم «آفاق التطوير» فهو توجهات تخضع للدراسة والاعتماد.", "vision": "أن تصل رسالة الحرمين الشريفين إلى العالم بلغاته، بترجمة موثوقة، وفي الوقت المناسب، وبما يليق بمكانتهما.", "mission": "إدارة أعمال ترجمة خطب الحرمين الشريفين ودروسهما ومواد الهيئة في منصة رقمية موحدة، تجمع الكفاءات المتخصصة، وتضبط مراحل العمل والصلاحيات، وتحفظ سرية المحتوى، وتوثق المسؤوليات، بالاستناد إلى بنية استضافة داخل المملكة العربية السعودية.", "stats": [["50", "لغة ترجمة في المنصة"], ["13", "لغة رئيسية"], ["6", "مراحل لكل لغة"], ["الرياض", "موقع الاستضافة"], ["يوميًّا", "نسخ احتياطي مشفّر"]], "goals": ["تعزيز جودة الترجمة: بتنظيم المراجعة الشرعية واللغوية، وضبط إجراءات اعتماد المخرجات.", "رفع كفاءة الإنجاز: بتوحيد الإسناد والمتابعة، وتحديد المواعيد، وتقليل الوقت المستغرق في تداول الملفات واستكمال الملاحظات.", "حماية المحتوى والبيانات: بتنظيم الوصول إلى المواد والوثائق، وتقييد تداولها بحسب الأدوار والصلاحيات.", "تطوير إدارة الكفاءات: بتوثيق بيانات الأعضاء ولغاتهم ومؤهلاتهم، ومتابعة أدائهم، وإسناد الأعمال وفق اختصاصاتهم.", "دعم التوسع واستمرارية العمل: بتهيئة المنصة لإضافة لغات جديدة، وبناء أرشيف منظم، وتحويل إجراءات العمل إلى ممارسة مؤسسية موثقة."], "stages": [["الترجمة", "المترجم", "إعداد الترجمة داخل المنصة، استنادًا إلى الأصل العربي، ووفق القالب المعتمد للهيئة."], ["المراجعة الشرعية", "المراجع الشرعي", "التحقق من سلامة المعاني الشرعية ودقة نقل الآيات والأحاديث والمصطلحات والأدلة."], ["المراجعة اللغوية", "المراجع اللغوي", "مراجعة سلامة اللغة والأسلوب والقواعد، ووضوح المعنى في اللغة المستهدفة."], ["التحرير والإخراج", "المحرر", "ضبط العناوين والتنسيق والصياغة التحريرية، وتهيئة المادة في صورتها النهائية."], ["المراجعة التنسيقية والاستلام", "المنسق", "التحقق من اكتمال المتطلبات والمراجعات، ومعالجة الملاحظات، وارتباط العمل بالنسخة الصحيحة من الأصل."], ["الاعتماد النهائي", "مدير المشروع", "اعتماد النسخة النهائية وإجازة تسليمها للنشر وفق الإجراءات والصلاحيات المقررة."]], "roles": [["مدير المشروع", ["يتولى الإشراف العام على المنصة، واعتماد مسارات العمل والصلاحيات، وإدارة الأدوار الإدارية، واعتماد المخرجات النهائية. كما يتولى اعتماد بطاقات العمل، والإشراف على توثيق البيانات البنكية، وإجراءات الأرشفة والحذف والاسترجاع وفق الصلاحيات المحددة."]], ["المنسق", ["يتولى إدخال المواد، وتحديد اللغات، وإسناد المهام، وضبط المواعيد، ومتابعة الإنجاز، واستلام الأعمال وإعادتها عند الحاجة بملاحظات واضحة.", "كما يتولى مراجعة طلبات الانضمام واستكمال إجراءات تفعيل الحسابات ضمن صلاحياته، وتحديد التعديلات على الأصل، وإرسال التعاميم ومتابعة الإقرار بالاطلاع عليها."]], ["المترجم والمراجع والمحرر", ["ينفذ كل عضو المهام المسندة إليه وفق اختصاصه واللغات المعتمدة له، ويعمل داخل المنصة على المواد المتاحة لحسابه، مع توثيق ملاحظاته ورفع المخرجات المطلوبة في المواعيد المحددة.", "ويتيح الحساب للعضو إدارة بياناته الشخصية والمصرفية، والاطلاع على تكليفاته ومراسلاته وبطاقة عمله بعد اعتمادها."]]], "sections": [["about", "عن المنصة", [["p", "منصة إدارة ترجمة خطب الحرمين الشريفين مبادرة رقمية طوّرتها إدارة مشروع خادم الحرمين الشريفين لترجمة خطب الحرمين الشريفين في جامعة أم القرى؛ لتوحيد أعمال الترجمة والمراجعة والاعتماد، وتنظيم التعاون بين فرق العمل في بيئة رقمية تحفظ المحتوى، وتوثق الإجراءات، وتدعم جودة الإنجاز."], ["p", "تُدار عبر المنصة ترجمة خطب المسجد الحرام والمسجد النبوي ودروسهما، وما يُسند إلى المشروع من مواد الهيئة العلمية والتوعوية والإرشادية، بدءًا من استلام المادة الأصلية، مرورًا بالترجمة والمراجعات المتخصصة، وانتهاءً باعتماد المخرجات وتجهيزها للنشر."], ["p", "وتجمع المنصة المادة الأصلية وترجماتها وملاحظاتها ومواعيدها في مكان واحد؛ لتكون لكل مادة نسخة مرجعية واضحة، ولكل مرحلة مسؤول معلوم، ولكل إجراء سجل يمكن الرجوع إليه."]]], ["vision", "الرؤية والرسالة", [["vision"]]], ["goals", "الأهداف", [["goals"]]], ["scope", "نطاق العمل والتغطية اللغوية", [["p", "تشمل أعمال المنصة خطب الجمعة والعيدين وعرفة والاستسقاء والكسوف، والدروس العلمية، والكتب والمطويات والمنشورات والإعلانات والتوجيهات، وفق نطاق الأعمال المسندة إلى المشروع."], ["p", "وتُصنَّف المواد بحسب نوعها وجهتها وتاريخها؛ فتُنسب الخطب والدروس إلى المسجد الحرام أو المسجد النبوي، وتُدرج المواد الأخرى ضمن التصنيفات المناسبة لها، بما يسهل إسنادها ومتابعتها والرجوع إليها."], ["diagram", "languages"], ["p", "تضم قائمة المنصة خمسين لغة ترجمة، من بينها ثلاث عشرة لغة رئيسية يمكن اختيارها ضمن مجموعة واحدة عند الإسناد. وتتيح إدارة اللغات إضافة لغات جديدة أو تعطيلها بحسب حاجة العمل وتوافر الكفاءات، دون الحاجة إلى تعديل برمجي في كل مرة."], ["p", "ويرتبط إسناد المهام باللغات المعتمدة لكل عضو؛ فلا تُسند إليه مهمة بلغة لم يُعتمد للعمل فيها. وتبقى اللغة العربية لغة الأصل الذي تُعد عنه الترجمات، ولا تدخل ضمن عدد لغات الترجمة."]]], ["how", "كيف تعمل المنصة؟", [["p", "تبدأ دورة العمل بإدخال المادة الأصلية وبياناتها، ثم تحديد اللغات المطلوبة، وإسناد المسؤوليات، وضبط مواعيد التسليم. ويُنشأ لكل لغة مسار مستقل يمكن متابعة تقدمه وحالته."], ["diagram", "cycle"], ["p", "يتكون المسار القياسي من ست مراحل:"], ["stages"], ["p", "تُضبط المراحل المطلوبة بحسب نوع المادة وطبيعتها، ضمن مسارات عمل معتمدة. والأصل في الخطب والمواد الشرعية استكمال المراجعتين الشرعية واللغوية قبل الاعتماد، فيما تُحدد متطلبات المواد الأخرى بما يتناسب مع محتواها والغرض منها."], ["p", "ويُتاح للمراجعين تعديل النص ضمن نطاق اختصاصهم، مع توثيق الملاحظات والتعديلات. ولا تُعاد المادة إلى مرحلة سابقة إلا بسبب مكتوب يوضح المطلوب، كما يُعاد أي تعديل لاحق يؤثر في المعنى إلى المراجعة المختصة قبل تجديد الاعتماد."], ["callout", "اعتماد الترجمة لا يعني إتاحتها للجمهور تلقائيًا؛ إذ يظل النشر مرتبطًا بالموعد والإذن المحددين من الجهة المختصة."]]], ["quality", "ضبط الجودة والمواعيد وإدارة التعديلات", [["p", "يرتبط كل تكليف بموعد تسليم محدد، وتُعرض للمسؤول عن المرحلة المدة المتبقية لإنجازها، مع مؤشرات واضحة عند تجاوز الموعد. ولا تُغلق المرحلة إلا بعد استيفاء متطلباتها، بما في ذلك رفع التسجيل الصوتي حين يكون جزءًا من التكليف."], ["p", "ويجمع تقييم الأداء بين جودة العمل، والالتزام بالمواعيد، والاستجابة للملاحظات، بالاستفادة من مؤشرات المتابعة الآلية والتقييم المهني للإدارة. وتُراعى أسباب الإعادة عند التقييم، بحيث يُميَّز بين الملاحظات المتعلقة بجودة العمل والتعديلات الناتجة عن تحديث الأصل أو تغير متطلبات التكليف. وتبقى نتائج التقييم متاحة للإدارة المخولة."], ["h3", "التعامل مع تحديث الأصل العربي"], ["p", "تراعي المنصة احتمال تعديل النص العربي بعد بدء العمل عليه. ويُوثَّق التحديث من خلال تحديد مواضع التعديل، أو إرفاق نسخة محدثة من الأصل مع حفظ النسخة السابقة، أو إضافة ملاحظة توضح التغيير المطلوب."], ["p", "ويحدد المنسق اللغات المتأثرة بالتعديل والمرحلة التي تعود إليها كل ترجمة، مع تمييز النسخة السارية من الأصل. وعندما يؤثر التعديل في ترجمة سبق اعتمادها، تُراجع الأجزاء المتأثرة قبل تجديد الاعتماد، ويُحدَّث التسجيل الصوتي عند الحاجة."], ["p", "وبذلك تظل كل ترجمة مرتبطة بأصل معلوم، ويُحدّ من الالتباس بين النسخ السابقة والنسخة النهائية."]]], ["team", "فريق العمل والأدوار والصلاحيات", [["roles"], ["h3", "الانضمام وتأهيل الأعضاء"], ["p", "يبدأ الانضمام بتقديم طلب تسجيل ومراجعة البيانات والمؤهلات، والتحقق من الكفاءة في اللغة والدور المطلوب وفق إجراءات المشروع. ولا يترتب على تقديم الطلب تفعيل الحساب أو منح الصلاحيات تلقائيًا."], ["p", "ويرتبط استلام المهام باستكمال متطلبات الانضمام والإقرار بالسرية. وتُضبط بيانات الهوية الأساسية بعد اعتمادها، ويكون تصحيحها من خلال إجراء موثق لدى الإدارة."]]], ["security", "السرية وحماية المحتوى والبيانات", [["p", "تُعامل المواد غير المنشورة بوصفها مواد مقيدة التداول، ولا تُتاح إلا للمخولين بالعمل عليها، وفي حدود ما تتطلبه مهامهم. ويُوثَّق إقرار الأعضاء بالسرية إلكترونيًا قبل استلام التكليفات."], ["diagram", "security"], ["p", "ويُعرض الأصل العربي داخل المنصة مع علامة مائية تتضمن معرّف المستخدم وتاريخ الاطلاع، وتُقيَّد إمكانات النسخ والتنزيل وفق الصلاحيات. وتهدف هذه الإجراءات إلى الحد من التداول غير المصرح به وتعزيز إمكانية تتبع الاطلاع على المادة."], ["p", "وتُطبق ضوابط الوصول على مستوى النظام وقاعدة البيانات، وليس في واجهة الاستخدام وحدها؛ بما يحصر وصول كل عضو إلى الأعمال والبيانات المصرح له بها."], ["p", "أما الوثائق الشخصية والمصرفية، فيقتصر الاطلاع عليها على صاحبها والمختصين المخولين، وتُستخدم روابط محدودة المدة للوصول إلى الملفات الخاصة ضمن الصلاحيات المحددة."], ["p", "وتُستخدم التنبيهات البريدية لإبلاغ الأعضاء بالتكليفات والمستجدات، مع إبقاء المحتوى المقيد داخل بيئة العمل. ولا يُسمح بمشاركة المواد غير المنشورة مع خدمات ترجمة أو أدوات ذكاء اصطناعي خارجية غير معتمدة."], ["callout", "إتاحة الترجمة للنشر لا تعني إتاحة بيانات العاملين عليها؛ إذ تظل بيانات الأعضاء ووثائقهم محمية وفق صلاحيات الاطلاع المقررة."]]], ["hosting", "الاستضافة داخل المملكة", [["p", "تعتمد المنصة على استضافة الخوادم وقاعدة البيانات والملفات في بيئة أوراكل السحابية بمدينة الرياض، داخل المملكة العربية السعودية، مع حفظ النسخ الاحتياطية في مخزن داخل المنطقة نفسها."], ["diagram", "hosting"], ["p", "ويُفصل الموقع العام المخصص للمستفيدين عن منصة العمل الداخلية، التي تعمل على عنوان فرعي مستقل؛ بما يميز بين المحتوى المتاح للجمهور والمواد والبيانات المقيدة. وتُستخدم اتصالات مشفرة لحماية البيانات أثناء انتقالها بين المستخدم والمنصة."], ["p", "ويمتد ضبط بيئة الاستضافة إلى الخدمات المساندة ومسارات الوصول وتبادل البيانات، بما في ذلك البريد وخدمات تسريع المحتوى؛ فلا يُعامل موقع الخادم وحده بوصفه كافيًا لضبط جميع جوانب التعامل مع البيانات."], ["p", "ويستند البناء التقني إلى مكونات مفتوحة المصدر قابلة للاستضافة الذاتية؛ بهدف زيادة التحكم في التشغيل والتطوير، وتيسير نقل النظام عند الحاجة، وتقليل الاعتماد على مزود واحد."]]], ["continuity", "النسخ الاحتياطي واستمرارية العمل", [["p", "تُنشأ نسخ احتياطية يومية تشمل قاعدة البيانات والملفات، وتُشفَّر قبل حفظها في مخزن النسخ الاحتياطية داخل المملكة، مع تقييد الوصول إليها وتنظيم مدد الاحتفاظ بها."], ["p", "وتشمل إجراءات التحقق من موثوقية النسخ اختبار استعادتها والتأكد من إمكان استرجاع البيانات والملفات بصورة متكاملة، إلى جانب متابعة نجاح عمليات النسخ ومعالجة أي خلل يظهر فيها."], ["p", "ويُراعى في تنظيم استمرارية العمل توثيق إجراءات التشغيل والاستعادة، وتحديد المسؤوليات وبدائلها، وتنظيم التعامل مع الأعطال؛ بما يدعم استعادة الخدمة والمحافظة على سير الأعمال."]]], ["governance", "الحوكمة والتوثيق والتواصل المؤسسي", [["p", "يرتبط بكل مادة سجل زمني يوضح إنشاءها، وإسناد مهامها، وانتقالها بين المراحل، والملاحظات والتعديلات التي أُجريت عليها، وأسباب إعادتها، وقرارات اعتمادها."], ["p", "وتُحمى سجلات الإجراءات من التعديل غير المصرح به، وتُستخدم مرجعًا للمتابعة والتقييم والمراجعة. كما تخضع عمليات حذف الأعمال واسترجاعها وإتلافها لصلاحيات وإجراءات محددة، مع توثيق القرارات المرتبطة بها."], ["p", "وتوفر المنصة قناة داخلية لإرسال التعاميم والتوجيهات والدعوات، نصًا أو بمرفقات، إلى جميع الأعضاء أو فئات محددة أو أشخاص بأعيانهم. ويُوثَّق اطلاع العضو وإقراره بالعلم، بما يتيح للإدارة متابعة الاستجابة دون الاعتماد على المراسلات المتفرقة."], ["p", "وتدعم الإشعارات متابعة سير العمل، من إبلاغ العضو بالمهمة وموعدها إلى تنبيه الإدارة باكتمال مراحل اللغة واستعدادها للإجراء التالي."]]], ["outputs", "مخرجات المنصة", [["cards", [["ترجمات معتمدة وجاهزة للتسليم", "نسخ نهائية لكل لغة على القالب الرسمي المعتمد للهيئة، قابلة للطباعة والتصدير بصيغتي Word وPDF، مع ضبط التنسيق وترقيم الصفحات."], ["أرشيف منظم للمواد والترجمات", "حفظ المواد المعتمدة وترجماتها وتسجيلاتها الصوتية، وتصنيفها بحسب نوع المادة وتاريخها وجهتها ولغتها؛ بما يسهل البحث والرجوع إليها وإعادة الاستفادة منها."], ["كشوف إدارية قابلة للتخصيص", "إعداد كشوف بيانات الفريق وتصديرها بصيغ Excel وWord وPDF، مع اختيار الأعضاء والحقول المطلوبة، وإضافة عنوان للكشف وخانات للتوقيع أو الحضور عند الحاجة، وفق صلاحيات الاطلاع والتصدير."], ["بطاقات عمل تعريفية", "إعداد بطاقات تتضمن صورة العضو وبياناته ورقم عضويته ولغاته، وإتاحتها في حسابه بعد اعتمادها، وفق التصميم والضوابط المعتمدة للمشروع."], ["بيانات منظمة لدعم إجراءات المستحقات", "تنظيم بيانات الحسابات البنكية داخل المملكة وخارجها والمستندات المؤيدة لها؛ لدعم مراجعتها واستكمال إجراءات المستحقات لدى الجهة المختصة، دون أن تكون المنصة بديلًا عن الإجراءات المالية المعتمدة."]]]]], ["future", "آفاق التطوير", [["p", "تمثل المسارات الآتية توجهات مستقبلية تخضع للدراسة والاعتماد، ولا تُعرض بوصفها وظائف منفذة ضمن النسخة الحالية:"], ["ul", ["التوسع اللغوي والأرشيفي: إضافة لغات وفق الحاجة وتوافر الكفاءات، وضم الترجمات السابقة إلى الأرشيف.", "التكامل مع قنوات النشر: ربط المخرجات بالقنوات الرسمية، مع المحافظة على ضوابط الاعتماد والإذن بالنشر.", "تطوير خدمات المستفيدين: دراسة توفير تطبيق للجوال ييسر الوصول إلى الترجمات والمحتوى المنشور.", "لوحات المؤشرات: عرض معدلات الإنجاز والالتزام بالمواعيد وأسباب الإعادة والتغطية اللغوية؛ لدعم المتابعة واتخاذ القرار.", "التكامل الصوتي: دراسة ربط التسجيلات بقنوات البث والنشر، وفق متطلبات المراجعة والتشغيل والتزامن."]]]], ["closing", "عمل مؤسسي موثَّق لخدمة رسالة الحرمين الشريفين", [["p", "تجمع المنصة بين الكفاءة البشرية والتنظيم الرقمي؛ لتكون المادة محفوظة، والمهمة محددة، والمراجعة موثقة، والنسخة النهائية معتمدة. ومن خلال هذه البيئة الموحدة، تدعم إدارة المشروع جودة الترجمة واستمرارية العمل والتوسع في خدمة المستفيدين، بما يليق برسالة الحرمين الشريفين ومكانتهما."]]]]}'::jsonb, now())
on conflict (key) do update set content = excluded.content, updated_at = now();
